/**
 * Custom Field: Email Input
 *
 * Params (set in custom field settings):
 *   - email: {{fields.email}}
 */
function customEmailField(context) {
  let input;
  let isExistingEmail = false;
  let isVerified = false;

  function buildInput() {

    const params = context.custom.getParams();
    console.log("customEmailField params:", JSON.stringify(params));

    const email = params.email || "";
    isExistingEmail = !!(email && email.trim() !== "");
const connType = params.connection_type || "";
applytranstionForm(email,connType);
    // Check all available sources for email_verified
    const hiddenFields = context.form.getAllHiddenFields() || {};
    console.log("hiddenFields:", JSON.stringify(hiddenFields));

    const verifiedValue = hiddenFields.email_verified
      || params.email_verified
      || "";

    console.log("email_verified resolved:", verifiedValue, "type:", typeof verifiedValue);
    isVerified = verifiedValue === "true" || verifiedValue === true;

    console.log("isExistingEmail:", isExistingEmail, "isVerified:", isVerified);

    input = document.createElement("input");
    input.type = "email";
    input.classList.add("af-stringField-input");
    input.id = "email";

    if (isExistingEmail) {
      input.value = email;
      input.readOnly = true;
      input.disabled = true;
      input.style.opacity = "0.7";
      input.style.cursor = "not-allowed";
    } else {
      input.value = "";
      input.placeholder = "Enter your email address";
      input.readOnly = false;
      input.disabled = false;
    }

    return input;
  }

  return {
    init() {
      return buildInput();
    },

    getScripts() {
      return [];
    },

    block() {
      if (input) input.disabled = true;
    },

    unblock() {
      if (input && !isExistingEmail) input.disabled = false;
    },

    getValue() {
      const emailValue = input ? input.value.trim() : "";
      const isNewEmail = !isExistingEmail && !!emailValue;
      const needsVerification = isNewEmail || (isExistingEmail && !isVerified);

      console.log("getValue - isVerified:", isVerified, "isNewEmail:", isNewEmail, "needs_verification:", needsVerification);

      return {
        email: emailValue,
        needs_verification: needsVerification,
      };
    },
  };
}

